import{z as A,x as s,o as e,c as _,q as B,j as o,D as t,d as E,s as r,S as n,b as l}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"流匹配","description":"","frontmatter":{"title":"流匹配","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/flow-matching.md","filePath":"llm/flow-matching.md","lastUpdated":1791413859000}'),d={name:"llm/flow-matching.md"};function p(m,a,D,x,h,c){const i=s("Mermaid");return e(),_("div",null,[a[2]||(a[2]=B('<h1 id="流匹配" tabindex="-1">流匹配 <a class="header-anchor" href="#流匹配" aria-label="Permalink to &quot;流匹配&quot;">​</a></h1><div class="epigraph"><p>不必把生成写成几百步马尔可夫去噪。学一条从噪声到数据的速度场，沿常微分方程积分即可。</p><footer>—— Lipman 等 Flow Matching for Generative Modeling；对照 Liu 等 Rectified Flow</footer></div><p><a href="/llm/ddpm">上一课</a>把生成钉在离散时间去噪。缺口是连续时间：路径可以选得更直，训练目标是匹配速度而不是逐步高斯后验。后课潜空间默认：无论扩散还是流，都仍可能先在像素上太贵，要压到 VAE 潜变量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DDPM 的 \\(T\\) 步与噪声日程是设计负担；采样是随机微分方程或离散高斯链。流匹配构造概率路径 \\(p_t\\)，其速度场 \\(u_t\\) 把简单先验（高斯）推到数据分布，沿 \\(\\dot x=u_t(x)\\) 的 ODE 积分即可采样。困难在于 \\(u_t\\) 没有闭式、无法直接回归；流匹配的解法从条件路径出发：抽一对 \\((x_0,x_1)\\)（先验样本与数据样本），沿插值</p> \\[x_t=(1-t)\\,x_0+t\\,x_1,\\qquad t\\in[0,1] \\]<p>条件速度就是常数 \\(v=x_1-x_0\\)——线性插值（独立耦合；Rectified Flow 称 OT 路径）的导数与 \\(t\\) 无关。网络 \\(v_\\theta(x,t)\\) 回归这个条件目标，其期望恰是边际速度场 \\(u_t(x)=\\mathbb E[x_1-x_0\\mid x_t=x]\\)：对条件目标回归与对边际场回归给出同一个梯度，所以不必知道 \\(u_t\\) 的闭式，采三元组 \\((x_0,x_1,t)\\) 就有无偏回归目标。可积性一句钉住合法性：边际分布 \\(p_t\\) 是各条件路径的混合，故沿拟合出的场积分，确实把 \\(\\mathcal N(0,I)\\) 推到数据分布。训练是回归，不是对抗。Rectified Flow 强调用直线路径连噪声与样本，积分更少步。</p><p>与理解侧 <a href="/llm/clip">CLIP</a> 无关：这里没有图文对比，只有连续状态上的向量场。条件生成同样把文本嵌入送进 \\(v_\\theta\\)。</p><p><span class="marginnote">直觉类比：把生成想成从「噪声停车场」开车去「数据目的地」。扩散模型给的是几百段带随机抖动的导航指令，走一步抖一下；流匹配直接学一张速度地图——每个位置该往哪开、开多快——沿着路积分到底就到了。</span></p><p><span class="marginnote">流与扩散在连续时间极限下可互通；产品差异是：训练目标（速度 vs 噪声/分数）、路径是否近直线、采样器是 ODE 还是随机。少步生成仍常靠蒸馏，见后课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>抽数据 \\(x_1\\)、先验 \\(x_0\\)、时间 \\(t\\)，按插值取 \\(x_t\\)，回归 \\(x_1-x_0\\)。采样解 ODE \\(\\dot x=v_\\theta(x,t)\\)，从 \\(t=0\\) 积到 \\(t=1\\)，欧拉步之外可换自适应求解器，步数是质量-延迟旋钮。与扩散对照着选路径：扩散的 VP 路径可写成同一插值族的非线性特例——系数 \\(\\bar\\alpha_t,\\bar\\sigma_t\\) 随 \\(t\\) 弯曲，DDPM 的离散链是它的随机离散化；直线版把「位置–速度」关系拉平，曲率小，欧拉法少步仍准。日程设计的负担从 \\(\\beta\\) 换成插值系数，但直线情形常只有一档，不必扫。评测仍是 FID 与条件遵守，不要用下一步交叉熵——那是离散 token 的账。</p><p><span class="marginnote">数字实例：取 \\(t=0.25\\)、\\(x_0\\) 为全零图、\\(x_1\\) 为某张真实图片，插值样本就是 \\(x_t=0.75\\times 0+0.25\\times x_1\\)——相当于原图以 25% 透明度叠在黑底上。网络要回归的目标 \\(x_1-x_0\\)，就是「从当前位置直指真实图片」的方向向量。</span></p>',13)),(e(),o(n,null,{default:t(()=>[r(i,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20N%5B%22%E5%85%88%E9%AA%8C%E5%99%AA%E5%A3%B0%22%5D%20--%3E%20ODE%5B%22%E6%B2%BF%E9%80%9F%E5%BA%A6%E5%9C%BA%E7%A7%AF%E5%88%86%22%5D%0A%20%20ODE%20--%3E%20D%5B%22%E6%95%B0%E6%8D%AE%E6%A0%B7%E6%9C%AC%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[E("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,"若路径是噪声与数据之间的直线，速度近似恒定，\\(v_\\theta\\) 更容易、积分步数可少：直线下 \\(x_t\\) 对 \\(t\\) 线性，网络要学的场在整条轨迹上近似常数，对没见过的 \\((x,t)\\) 插值也稳；弯曲路径则把难度推给网络与求解器——速度沿轨迹旋转，求解器每步都要重新评估，步数下不来。这解释了为何同参数量下「直的流」少步更稳，而不是魔法替代了表示学习——表示仍由骨干与数据决定。轨迹还不够直时，可把训好的模型自己采样出的配对再当训练对重训（reflow 类操作），逐次拉直，为一步生成铺路。",-1)),(e(),o(n,null,{default:t(()=>[r(i,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%9B%B4%E7%BA%BF%E8%B7%AF%E5%BE%84%EF%BC%88%E7%BA%BF%E6%80%A7%E6%8F%92%E5%80%BC%EF%BC%89%22%5D%20--%3E%20B%5B%22%E9%80%9F%E5%BA%A6%E5%9C%BA%E8%BF%91%E4%BC%BC%E5%B8%B8%E6%95%B0%22%5D%0A%20%20B%20--%3E%20C%5B%22%E7%BD%91%E7%BB%9C%E5%A5%BD%E5%AD%A6%EF%BC%8C%E6%AC%A7%E6%8B%89%E5%A4%A7%E6%AD%A5%E4%B9%9F%E4%B8%8D%E5%87%BA%E8%BD%A8%22%5D%0A%20%20C%20--%3E%20D%5B%22%E5%B0%91%E6%AD%A5%E9%87%87%E6%A0%B7%E5%8F%AF%E8%A1%8C%22%5D%0A%20%20E%5B%22%E5%BC%AF%E6%9B%B2%E8%B7%AF%E5%BE%84%EF%BC%88%E5%A6%82%20VP%EF%BC%89%22%5D%20--%3E%20F%5B%22%E9%80%9F%E5%BA%A6%E6%B2%BF%E8%BD%A8%E8%BF%B9%E4%B8%8D%E6%96%AD%E8%BD%AC%E5%90%91%22%5D%0A%20%20F%20--%3E%20G%5B%22%E6%B1%82%E8%A7%A3%E5%99%A8%E5%8F%AA%E8%83%BD%E5%B0%8F%E6%AD%A5%E9%87%8D%E4%BC%B0%22%5D%0A%20%20G%20--%3E%20H%5B%22%E6%AD%A5%E6%95%B0%E5%B1%85%E9%AB%98%E4%B8%8D%E4%B8%8B%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<p><span class="marginnote">为什么重要：路径越直，速度场越接近常数，采样用大步也不出错；弯曲路径每步都要小心翼翼，几十步起步。这就是 Rectified Flow、Flux 一类「直线流」敢主打少步快采样的全部底气——不是模型更聪明，是路修得更直。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>流不自动给出离散视觉词表，接自回归 LLM 仍要量化或另做连续头。少步若还不够，蒸馏在后课。下一课先把昂贵的像素生成挪到潜空间。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>流匹配学速度场，用 ODE 从先验走到数据；回归目标 \\(x_1-x_0\\) 无偏可采。</li><li>边际速度场可积，混合条件路径即概率路径，训练只需三元组。</li><li>直路径减少积分步，与 DDPM 的长链不同。</li><li>目标是回归，不是词表 CE。</li><li>出处：Lipman 等 Flow Matching；Liu 等 Rectified Flow。</li></ul>',5))])}const u=A(d,[["render",p]]);export{F as __pageData,u as default};
